{"implementation": "def solve(case):
    # Validate top-level structure
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if "threshold" not in case:
        raise ValueError("Missing required field: threshold")
    if "calls" not in case:
        raise ValueError("Missing required field: calls")

    threshold = case["threshold"]
    calls = case["calls"]

    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be numeric")
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")

    REQUIRED_CALL_FIELDS = (
        "call_id",
        "loss_without_call",
        "loss_with_call",
        "prediction_tokens",
        "parseable",
    )

    accepted_call_ids = []
    diagnostics = []

    for idx, call in enumerate(calls):
        if not isinstance(call, dict):
            raise ValueError(f"Call at index {idx} must be a dict")
        for field in REQUIRED_CALL_FIELDS:
            if field not in call:
                raise ValueError(
                    f"Call at index {idx} missing required field: {field}"
                )

        call_id = call["call_id"]
        loss_without = call["loss_without_call"]
        loss_with = call["loss_with_call"]
        n_tokens = call["prediction_tokens"]
        parseable = call["parseable"]

        if not isinstance(loss_without, (int, float)):
            raise ValueError(f"loss_without_call must be numeric for call {call_id}")
        if not isinstance(loss_with, (int, float)):
            raise ValueError(f"loss_with_call must be numeric for call {call_id}")
        if not isinstance(n_tokens, int) or n_tokens < 1:
            raise ValueError(
                f"prediction_tokens must be a positive integer for call {call_id}"
            )
        if not isinstance(parseable, bool):
            raise ValueError(f"parseable must be a boolean for call {call_id}")

        # Stronger counterfactual: gain from having the call
        gain = loss_without - loss_with

        # Normalize by prediction token count (at least 1, enforced by validation above)
        normalized_gain = gain / n_tokens

        # Inclusive threshold: accept when parseable AND normalized_gain >= threshold
        accepted = parseable and (normalized_gain >= threshold)

        if accepted:
            accepted_call_ids.append(call_id)

        diagnostics.append(
            {
                "call_id": call_id,
                "gain": round(gain, 8),
                "normalized_gain": round(normalized_gain, 8),
                "parseable": parseable,
                "accepted": accepted,
            }
        )

    return {
        "accepted_call_ids": accepted_call_ids,
        "total_accepted": len(accepted_call_ids),
        "diagnostics": diagnostics,
    }
